-- 0014_kb_procurement_law.sql
-- คลังความรู้ (KB) เนื้อหา พ.ร.บ.การจัดซื้อจัดจ้างและการบริหารพัสดุภาครัฐ พ.ศ. 2560
-- สรุปจากแหล่งข้อมูลสาธารณะ (ราชกิจจานุเบกษา, กรมบัญชีกลาง, เอกสารสรุปของหน่วยงานราชการ) เพื่อใช้เป็น
-- ฐานความรู้ให้ AI ตอบคำถามนักเรียนเบื้องต้น — **ไม่ใช่ตัวบทกฎหมายฉบับสมบูรณ์**
-- ปิดใช้งานไว้ก่อน (enabled=false) โดยตั้งใจ — ให้ผู้สอน/ผู้เชี่ยวชาญตรวจทานความถูกต้อง/ความทันสมัย
-- ก่อนเปิดใช้จริงที่หน้า "คลังความรู้ AI" ในระบบ (กฎหมาย/ระเบียบอาจมีการแก้ไขเพิ่มเติมภายหลัง)

insert into kb_articles (title, body, keywords, category, enabled) values

('ภาพรวมและวัตถุประสงค์ พ.ร.บ.จัดซื้อจัดจ้างภาครัฐ',
 'พระราชบัญญัติการจัดซื้อจัดจ้างและการบริหารพัสดุภาครัฐ พ.ศ. 2560 ประกาศในราชกิจจานุเบกษาวันที่ 24 กุมภาพันธ์ 2560 มีผลใช้บังคับตั้งแต่ 23 สิงหาคม 2560 ใช้บังคับกับหน่วยงานของรัฐทุกแห่ง ทั้งราชการส่วนกลาง ส่วนภูมิภาค ส่วนท้องถิ่น รัฐวิสาหกิจ องค์การมหาชน และหน่วยงานอื่นของรัฐ วัตถุประสงค์หลักคือทำให้การจัดซื้อจัดจ้างมีความคุ้มค่า โปร่งใส มีประสิทธิภาพและประสิทธิผล สามารถตรวจสอบได้ และเปิดโอกาสให้ภาคเอกชนแข่งขันกันเสนอราคาอย่างเป็นธรรม',
 array['พรบ','พระราชบัญญัติ','จัดซื้อจัดจ้าง','วัตถุประสงค์','2560','ประกาศใช้','บังคับใช้','หน่วยงานของรัฐ'],
 'ภาพรวมกฎหมาย', false),

('คณะกรรมการหลักตาม พ.ร.บ.จัดซื้อจัดจ้าง',
 'พ.ร.บ.กำหนดให้มีคณะกรรมการหลัก 5 ชุด: (1) คณะกรรมการนโยบายการจัดซื้อจัดจ้างและการบริหารพัสดุภาครัฐ — กำหนดนโยบายภาพรวม (2) คณะกรรมการวินิจฉัยปัญหาการจัดซื้อจัดจ้างและการบริหารพัสดุภาครัฐ — ตีความ/วินิจฉัยปัญหาข้อกฎหมาย (3) คณะกรรมการราคากลางและขึ้นทะเบียนผู้ประกอบการ — กำหนดหลักเกณฑ์ราคากลางและขึ้นทะเบียนผู้ประกอบการ (4) คณะกรรมการความร่วมมือป้องกันการทุจริต (ค.ป.ท.) — ดูแลข้อตกลงคุณธรรม (Integrity Pact) (5) คณะกรรมการพิจารณาอุทธรณ์และข้อร้องเรียน — วินิจฉัยชี้ขาดอุทธรณ์ผลการจัดซื้อจัดจ้าง',
 array['คณะกรรมการ','นโยบาย','วินิจฉัย','ราคากลาง','คปท','ป้องกันการทุจริต','อุทธรณ์','ข้อร้องเรียน'],
 'ภาพรวมกฎหมาย', false),

('นิยามศัพท์สำคัญในกฎหมายจัดซื้อจัดจ้าง',
 'หน่วยงานของรัฐ หมายถึง ราชการส่วนกลาง ส่วนภูมิภาค ส่วนท้องถิ่น รัฐวิสาหกิจ องค์การมหาชน องค์กรอิสระ องค์กรตามรัฐธรรมนูญ และหน่วยงานอื่นที่กฎหมายกำหนด พัสดุ หมายถึง สินค้า งานบริการ งานก่อสร้าง งานจ้างที่ปรึกษา งานจ้างออกแบบหรือควบคุมงานก่อสร้าง และการดำเนินการอื่นตามที่กำหนดในกฎกระทรวง การจัดซื้อจัดจ้าง หมายถึง การดำเนินการเพื่อให้ได้มาซึ่งพัสดุโดยการซื้อ จ้าง เช่า แลกเปลี่ยน หรือโดยนิติกรรมอื่นตามหลักเกณฑ์ที่กำหนด',
 array['นิยาม','คำจำกัดความ','หน่วยงานของรัฐ','พัสดุ','การจัดซื้อจัดจ้าง'],
 'ภาพรวมกฎหมาย', false),

('วิธีการจัดซื้อจัดจ้าง 3 วิธีหลัก',
 'การจัดซื้อจัดจ้างพัสดุกระทำได้ 3 วิธี: (1) วิธีประกาศเชิญชวนทั่วไป — เปิดกว้างให้ผู้ประกอบการทั่วไปยื่นข้อเสนอ แบ่งเป็นวิธีตลาดอิเล็กทรอนิกส์ (e-market) และวิธีประกวดราคาอิเล็กทรอนิกส์ (e-bidding) (2) วิธีคัดเลือก — เชิญเฉพาะผู้ประกอบการที่มีคุณสมบัติตรงเงื่อนไขอย่างน้อย 3 รายมายื่นข้อเสนอ ใช้เมื่อมีข้อจำกัดด้านเทคนิค/ความลับ/ความเร่งด่วน (3) วิธีเฉพาะเจาะจง — เชิญผู้ประกอบการรายใดรายหนึ่งเข้าเสนอราคาหรือเจรจาต่อรองโดยตรง ใช้เมื่อวงเงินไม่เกิน 500,000 บาท หรือมีเหตุจำเป็นเร่งด่วน/ผูกขาด/ต่อเนื่องจากสัญญาเดิม',
 array['วิธีจัดซื้อจัดจ้าง','ประกาศเชิญชวนทั่วไป','วิธีคัดเลือก','วิธีเฉพาะเจาะจง','e-market','e-bidding','3 วิธี'],
 'วิธีจัดซื้อจัดจ้าง', false),

('e-market และ e-bidding รายละเอียด',
 'วิธีตลาดอิเล็กทรอนิกส์ (e-market) ใช้กับพัสดุที่มีรายละเอียดคุณลักษณะเฉพาะไม่ซับซ้อน และมีในระบบบัญชีข้อมูลสินค้า (e-catalog) มี 2 รูปแบบ: การเสนอราคาด้วยใบเสนอราคา (RFQ) สำหรับวงเงินไม่เกิน 5,000,000 บาท และการเสนอราคาด้วยการประมูลอิเล็กทรอนิกส์ (e-Auction) สำหรับวงเงินเกิน 5,000,000 บาท วิธีประกวดราคาอิเล็กทรอนิกส์ (e-bidding) ใช้กับพัสดุที่มีวงเงินเกิน 500,000 บาทขึ้นไป ที่ไม่มีรายละเอียดกำหนดไว้ใน e-catalog หรือมีวงเงินเกิน 5,000,000 บาทแม้จะมีใน e-catalog ต้องประกาศเชิญชวนผ่านระบบ e-GP',
 array['e-market','e-bidding','e-catalog','e-auction','ประมูลอิเล็กทรอนิกส์','ตลาดอิเล็กทรอนิกส์','วงเงิน 5 ล้าน'],
 'วิธีจัดซื้อจัดจ้าง', false),

('วิธีคัดเลือก — เงื่อนไขการใช้',
 'หน่วยงานของรัฐจะใช้วิธีคัดเลือกได้ในกรณีดังนี้: (1) ใช้วิธีประกาศเชิญชวนทั่วไปแล้วไม่มีผู้ยื่นข้อเสนอ หรือข้อเสนอที่ยื่นไม่ถูกต้องตามเงื่อนไข (2) พัสดุมีความจำเป็นเร่งด่วน หากใช้วิธีประกาศเชิญชวนทั่วไปจะทำให้การดำเนินงานล่าช้าและอาจเสียหาย (3) เป็นพัสดุที่มีผู้ผลิต/จำหน่าย/ให้บริการเฉพาะรายน้อยกว่า 3 ราย (4) เป็นพัสดุที่ใช้เทคนิคเฉพาะที่มีผู้ประกอบการมีคุณสมบัติโดยตรงจำนวนน้อยราย (5) เป็นงานก่อสร้างหรือบริการที่ต้องปกปิดเป็นความลับทางราชการ (6) มีความจำเป็นต้องซื้อหรือจ้างเพิ่มเติม (Repeat Order) จากผู้ประกอบการรายเดิม',
 array['วิธีคัดเลือก','เงื่อนไข','กรณีใช้วิธีคัดเลือก','repeat order','งานลับ'],
 'วิธีจัดซื้อจัดจ้าง', false),

('วิธีเฉพาะเจาะจง — เกณฑ์วงเงินและหลักเกณฑ์',
 'หน่วยงานของรัฐใช้วิธีเฉพาะเจาะจงได้เมื่อวงเงินการจัดซื้อจัดจ้างครั้งหนึ่งไม่เกิน 500,000 บาท (ตามมาตรา 56 วรรคหนึ่ง (2)(ข)) หรือในกรณีอื่น เช่น มีความจำเป็นเร่งด่วนที่ไม่ได้คาดหมายไว้ก่อนและไม่อาจดำเนินการตามวิธีอื่นได้ทัน, เป็นพัสดุที่จะขายทอดตลาดโดยหน่วยงานของรัฐ, เป็นที่ดินหรือสิ่งปลูกสร้างที่จำเป็นต้องซื้อเฉพาะแห่ง, เป็นการซื้อหรือจ้างจากหน่วยงานของรัฐด้วยกัน, หรือใช้วิธีคัดเลือกแล้วไม่ได้ผล วิธีนี้เจ้าหน้าที่จะเจรจาตกลงราคากับผู้ประกอบการรายใดรายหนึ่งโดยตรง ไม่ต้องประกาศเชิญชวนทั่วไป',
 array['วิธีเฉพาะเจาะจง','500000','ห้าแสนบาท','มาตรา 56','เกณฑ์วงเงิน','เจรจาต่อรอง'],
 'วิธีจัดซื้อจัดจ้าง', false),

('การทำสัญญาและบริหารสัญญา',
 'เมื่อคัดเลือกผู้ชนะการเสนอราคาแล้ว หน่วยงานของรัฐต้องทำสัญญาเป็นหนังสือ ยกเว้นกรณีวงเงินเล็กน้อยอาจไม่ต้องทำเป็นหนังสือตามระเบียบ สัญญาโดยทั่วไปต้องมีหลักประกันสัญญา (โดยปกติประมาณร้อยละ 5 ของวงเงินตามสัญญา) การแก้ไขสัญญาทำได้เมื่อมีความจำเป็นและไม่ทำให้ทางราชการเสียประโยชน์ กรณีคู่สัญญาผิดสัญญาหรือส่งมอบงานล่าช้ากว่ากำหนด หน่วยงานต้องคิดค่าปรับตามอัตราที่กำหนดไว้ในสัญญา และต้องแต่งตั้งคณะกรรมการตรวจรับพัสดุหรือผู้ควบคุมงานเพื่อตรวจสอบการส่งมอบให้ตรงตามสัญญาก่อนเบิกจ่ายเงิน',
 array['สัญญา','บริหารสัญญา','หลักประกันสัญญา','ค่าปรับ','แก้ไขสัญญา','ตรวจรับพัสดุ'],
 'สัญญาและการตรวจรับ', false),

('การบริหารพัสดุ: เก็บ เบิกจ่าย ตรวจสอบ จำหน่าย',
 'การบริหารพัสดุ หมายถึง การเก็บรักษา การบันทึกบัญชี การเบิกจ่าย การยืม การตรวจสอบ และการจำหน่ายพัสดุ หน่วยงานของรัฐต้องจัดให้มีการตรวจสอบพัสดุประจำปีอย่างน้อยปีละ 1 ครั้ง โดยแต่งตั้งเจ้าหน้าที่ตรวจสอบพัสดุซึ่งไม่ใช่เจ้าหน้าที่พัสดุประจำ พัสดุที่ชำรุด เสื่อมสภาพ สูญไป หรือไม่จำเป็นต้องใช้ในหน่วยงานอีกต่อไป ให้ดำเนินการจำหน่ายโดยวิธีขายทอดตลาด แลกเปลี่ยน โอนให้หน่วยงานอื่น หรือแปรสภาพ/ทำลาย ตามหลักเกณฑ์ที่กำหนดในระเบียบ',
 array['บริหารพัสดุ','เก็บรักษา','เบิกจ่าย','ตรวจสอบพัสดุประจำปี','จำหน่ายพัสดุ','ขายทอดตลาด'],
 'บริหารพัสดุ', false),

('บทกำหนดโทษ',
 'เจ้าหน้าที่หรือผู้มีอำนาจหน้าที่ที่ปฏิบัติหรือละเว้นการปฏิบัติหน้าที่โดยมิชอบ ก่อให้เกิดความเสียหายแก่หน่วยงานของรัฐ หรือปฏิบัติหน้าที่โดยทุจริต มีความผิดต้องระวางโทษจำคุกและ/หรือปรับตามที่กฎหมายกำหนด ผู้ประกอบการที่เข้าเสนอราคาโดยไม่สุจริต สมยอมกันในการเสนอราคา (ฮั้วประมูล) หรือกระทำการอันเป็นการขัดขวางการแข่งขันราคาอย่างเป็นธรรม มีความผิดต้องระวางโทษเช่นกัน และอาจถูกเพิกถอนสิทธิ ขึ้นบัญชีเป็นผู้ทิ้งงาน ห้ามเข้าเสนอราคาหรือทำสัญญากับหน่วยงานของรัฐ',
 array['บทกำหนดโทษ','ผู้ทิ้งงาน','ฮั้วประมูล','ทุจริต','โทษจำคุก','เพิกถอนสิทธิ'],
 'บทลงโทษ', false),

('การอุทธรณ์ผลการจัดซื้อจัดจ้าง',
 'ผู้ยื่นข้อเสนอที่ไม่ได้รับการคัดเลือกและไม่เห็นด้วยกับผลการพิจารณา มีสิทธิยื่นอุทธรณ์ต่อหน่วยงานของรัฐภายใน 7 วันทำการนับแต่วันที่ประกาศผลการจัดซื้อจัดจ้าง หน่วยงานของรัฐต้องพิจารณาอุทธรณ์เบื้องต้นให้แล้วเสร็จภายใน 7 วันทำการ หากผู้อุทธรณ์ไม่เห็นด้วยกับผลการพิจารณา สามารถส่งเรื่องต่อคณะกรรมการพิจารณาอุทธรณ์และข้อร้องเรียน (กรมบัญชีกลาง) เพื่อวินิจฉัยชี้ขาดต่อไป',
 array['อุทธรณ์','ข้อร้องเรียน','7 วันทำการ','คณะกรรมการพิจารณาอุทธรณ์','กรมบัญชีกลาง'],
 'สัญญาและการตรวจรับ', false);

-- ตรวจสอบ: select id, title, category, enabled from kb_articles order by id;
-- เปิดใช้งานทีละบทความ (หลังตรวจทานแล้ว) ที่หน้า "คลังความรู้ AI" ในระบบ หรือรันคำสั่งนี้เพื่อเปิดทั้งหมดพร้อมกัน:
-- update kb_articles set enabled = true where category in ('ภาพรวมกฎหมาย','วิธีจัดซื้อจัดจ้าง','สัญญาและการตรวจรับ','บริหารพัสดุ','บทลงโทษ');
